<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor\UserWebauthnCredentialTransportsJsonAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialTransportsJsonAccessor trait.
 *
 * Covers null default, string/VO assignment via withTransportsJson,
 * getTransportsJson/transportsJson accessors, and isTransportsJsonChanged with/without original.
 */
class UserWebauthnCredentialTransportsJsonAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTransportsJson creates a new instance with the TransportsJson set
     * from a string value, and getTransportsJson returns the primitive string.
     */
    public function testWithTransportsJsonFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialTransportsJsonAccessorUnitTest();

        // Act
        $result = $holder->withTransportsJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getTransportsJson());
    }
    /**
     * Asserts that withtransportsJson has access to the value object
     * from a string value, and getTransportsJson returns the primitive string.
     */
    public function testWithTransportsJsonFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialTransportsJsonAccessorUnitTest();

        // Act
        $result = $holder->withTransportsJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->transportsJson()->value());
    }
    public function testChangedTransportsJson(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialTransportsJsonAccessorUnitTest();
        $original = $holder->withTransportsJson('one');
        $same = $holder->withTransportsJson('one');
        $modified = $holder->withTransportsJson('other');

        // Act
        $unchanged = $holder->isTransportsJsonChanged();
        $withSame = $original->isTransportsJsonChanged($same);
        $withDiferent = $original->isTransportsJsonChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWebauthnCredentialTransportsJsonAccessorUnitTest
{
    use UserWebauthnCredentialTransportsJsonAccessor;
}
